// The themes' `.zi` files, as URLs the browser can fetch.
//
// They are real binaries in the repository (`themes/<id>/fonts/`),
// generated by `export/scripts/build-theme-fonts.mjs`. Vite hashes and
// serves them like any other asset, so this only has to match what a design
// system DECLARES (`font.file`) with what is on disk.
//
// A declaration with no file is not a crash and not a silent blank: it comes
// back `undefined` and the caller says so on screen: a theme can declare fonts
// it does not ship.
import type { Theme, FontToken } from "@nspanel-sim/core";
import { themeDirs } from "./content";

const fontUrls = import.meta.glob("../../themes/*/fonts/*.zi", {
  eager: true,
  query: "?url",
  import: "default",
}) as Record<string, string>;

/** The URL of one declared font, or `undefined` when the file is not there. */
export function fontUrl(system: Theme, font: FontToken): string | undefined {
  const dir = themeDirs.get(system.id);
  if (dir === undefined) return undefined;
  return fontUrls[`../../themes/${dir}/${font.file}`];
}

/** Every `.zi` on disk for a theme, whether or not it was declared. */
export function fontFilesOnDisk(system: Theme): string[] {
  const dir = themeDirs.get(system.id);
  if (dir === undefined) return [];
  const prefix = `../../themes/${dir}/`;
  return Object.keys(fontUrls)
    .filter((k) => k.startsWith(prefix))
    .map((k) => k.slice(prefix.length))
    .sort();
}

/**
 * The resolved icon roles of each theme, generated next to its fonts by
 * `build-theme-fonts.mjs`. Eager, because it is a few hundred bytes and
 * the panel needs it before the first paint -- an icon that arrives a frame late
 * flickers through its Material fallback.
 */
const roleTables = import.meta.glob("../../themes/*/fonts/icon-roles.generated.json", {
  eager: true,
  import: "default",
}) as Record<string, Record<string, { name: string; code: number; path: string }>>;

export function iconRolesOf(system: Theme): Record<string, { name: string; code: number; path: string }> {
  const dir = themeDirs.get(system.id);
  if (dir === undefined) return {};
  const font = system.fonts.find((f) => system.icons.fonts.includes(f.id));
  if (font === undefined) return {};
  const key = `../../themes/${dir}/${font.file.replace(/[^/]+$/, "")}icon-roles.generated.json`;
  return roleTables[key] ?? {};
}

/**
 * The URLs of every font the icons live in. Plural because icon size is a font
 * choice, not a scale: a theme carries the heights it needs and a
 * component picks the largest that fits its box.
 */
export function iconFontUrls(system: Theme): string[] {
  return system.icons.fonts
    .map((id) => system.fonts.find((f) => f.id === id))
    .map((f) => (f ? fontUrl(system, f) : undefined))
    .filter((u): u is string => u !== undefined);
}

/**
 * What each theme's `.zi` files turned out to carry, generated next to them by
 * `build-theme-fonts.mjs`.
 *
 * The other half of `typeface.family`. The theme declares the face it ASKS for;
 * this is read from the files themselves, so the two cannot be typed into
 * agreement — and for two of the three themes here they do not agree, because
 * the only source we have to cut a `.zi` from is the joBr99 project's Noto Sans.
 * Saying so on screen is the point; before this the disagreement was invisible.
 */
const typefaceTables = import.meta.glob("../../themes/*/fonts/typeface.generated.json", {
  eager: true,
  import: "default",
}) as Record<string, CarriedTypeface>;

export interface CarriedTypeface {
  /** the family the theme asked for */
  asked: string;
  /** font id -> what its `.zi` actually is */
  fonts: Record<string, { ziName: string; weight: number; height: number; antiAlias: boolean }>;
  /** the distinct face names across the theme's fonts */
  carriedNames: string[];
}

export function carriedTypefaceOf(theme: Theme): CarriedTypeface | undefined {
  const dir = themeDirs.get(theme.id);
  if (dir === undefined) return undefined;
  const font = theme.fonts.find((f) => theme.icons.fonts.includes(f.id)) ?? theme.fonts[0];
  if (font === undefined) return undefined;
  return typefaceTables[`../../themes/${dir}/${font.file.replace(/[^/]+$/, "")}typeface.generated.json`];
}
